import { useLayoutEffect, useRef, useState, type ComponentProps } from "react"
import { ArrowUpFromLine, Clock, ExternalLink, MoreHorizontal } from "lucide-react"
import { AppVersions } from "@/components/AppVersions"
import { Button } from "@/components/ui/button"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuShortcut, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Kbd } from "@/components/ui/kbd"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useAppPreview } from "@/lib/use-app-preview"
import { cn } from "@/lib/utils"

type Props = Omit<ComponentProps<typeof AppVersions>, "session" | "open" | "onOpenChange" | "overflowAnchor"> & {
  session: ComponentProps<typeof AppVersions>["session"] | null
  publishing: boolean
  publishDisabled: boolean
  onPublish: () => void
  osShortcut: "cmd" | "ctrl"
}

/** One mounted Versions/preview lifecycle, two presentations of the same actions. */
export function AppWorkspaceActions({ session, publishing, publishDisabled, onPublish, osShortcut, ...versionsProps }: Props) {
  const rootRef = useRef<HTMLDivElement>(null)
  const rowRef = useRef<HTMLDivElement>(null)
  const moreRef = useRef<HTMLButtonElement>(null)
  const openingPublishDialog = useRef(false)
  const [compact, setCompact] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [versionsOpen, setVersionsOpen] = useState(false)
  const preview = useAppPreview(session, versionsProps.disabled || Boolean(session?.offline))
  const shortcut = osShortcut === "cmd" ? "⌘S" : "Ctrl S"

  useLayoutEffect(() => {
    const toolbar = rootRef.current?.closest<HTMLElement>('[data-slot="settings-panel-toolbar"]')
    const navigation = toolbar?.querySelector<HTMLElement>('[aria-label="Editor panels"]')
    const row = rowRef.current
    if (!toolbar || !navigation || !row) return
    const measure = () => {
      const width = toolbar.getBoundingClientRect().width
      if (!width) return
      const style = getComputedStyle(toolbar)
      const available = width - (parseFloat(style.paddingLeft) || 0) - (parseFloat(style.paddingRight) || 0)
        - navigation.getBoundingClientRect().width - (parseFloat(style.columnGap) || 0)
      const nextCompact = row.getBoundingClientRect().width > available
      setCompact(nextCompact)
      if (!nextCompact) setMenuOpen(false)
    }
    const observer = new ResizeObserver(measure)
    for (const element of [toolbar, navigation, row]) observer.observe(element)
    measure()
    return () => observer.disconnect()
  }, [])

  return <div ref={rootRef} className="relative flex min-w-0 items-center">
    {/* Keep the real row measurable and mounted, including migration notices and save status. */}
    <div ref={rowRef} data-slot="workspace-actions-expanded" aria-hidden={compact || undefined} inert={compact}
      className={cn("flex w-max shrink-0 items-center gap-2", compact && "pointer-events-none invisible absolute right-0 top-0")}>
      {session ? <AppVersions {...versionsProps} session={session} open={versionsOpen} onOpenChange={setVersionsOpen} overflowAnchor={compact ? moreRef : undefined} /> : null}
      {session ? <Tooltip><TooltipTrigger asChild>
        <Button type="button" size="xs" variant="outline" disabled={preview.disabled} onClick={() => void preview.preview()}>
          <ExternalLink />{preview.busy ? "Opening…" : "Preview"}
        </Button>
      </TooltipTrigger><TooltipContent side="bottom">Preview current draft</TooltipContent></Tooltip> : null}
      <Tooltip><TooltipTrigger asChild>
        <Button type="button" size="xs" disabled={publishDisabled} onClick={onPublish}>{publishing ? "Publishing..." : "Publish"}</Button>
      </TooltipTrigger><TooltipContent side="bottom" className="flex items-center gap-2"><span>Publish changes</span><Kbd>{shortcut}</Kbd></TooltipContent></Tooltip>
    </div>
    {compact ? <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
      <Tooltip><TooltipTrigger asChild><DropdownMenuTrigger asChild>
        <Button ref={moreRef} type="button" size="icon-xs" variant="ghost" aria-label="Show more"><MoreHorizontal /></Button>
      </DropdownMenuTrigger></TooltipTrigger><TooltipContent side="bottom">Show more</TooltipContent></Tooltip>
      <DropdownMenuContent align="end" onCloseAutoFocus={event => {
        if (versionsOpen || openingPublishDialog.current) event.preventDefault()
        openingPublishDialog.current = false
      }}>
        <DropdownMenuItem disabled={versionsProps.disabled || !session?.ready} onSelect={() => setVersionsOpen(true)}><Clock />Versions</DropdownMenuItem>
        <DropdownMenuItem disabled={preview.disabled} onSelect={() => void preview.preview()}><ExternalLink />{preview.busy ? "Opening…" : "Preview"}</DropdownMenuItem>
        <DropdownMenuItem disabled={publishDisabled} onSelect={() => { openingPublishDialog.current = true; onPublish() }}><ArrowUpFromLine />{publishing ? "Publishing..." : "Publish"}<DropdownMenuShortcut>{shortcut}</DropdownMenuShortcut></DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu> : null}
    {preview.error ? <span role="alert" className="absolute right-0 top-full z-10 w-64 rounded border bg-background p-2 text-xs text-destructive">{preview.error}</span> : null}
  </div>
}
