import { useState } from "react"
import type { AppDraftSession, AppSnapshot } from "@/lib/app-drafts"
import { getAdminMapInstance } from "@/lib/apply-options-patch"

/** Shared toolbar/menu action; open the tab within the original user gesture. */
export function useAppPreview(session: AppDraftSession | null, disabled: boolean) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  async function preview() {
    if (!session) return
    setError(null)
    const tab = window.open("about:blank", "_blank")
    if (!tab) { setError("Allow popups to open preview."); return }
    tab.opener = null
    setBusy(true)
    try {
      const map = getAdminMapInstance()
      if (map?.id === session.mapId) session.capture(map.getData!() as AppSnapshot)
      tab.location.href = await session.preview()
    } catch (error) {
      tab.close()
      setError(error instanceof Error ? error.message : String(error))
    } finally { setBusy(false) }
  }
  return {
    busy, error, preview,
    disabled: disabled || busy || !session?.ready || !session.active || session.busy || session.transitioning || Boolean(session.active?.conflicted),
  }
}
